import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import time

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
ALLOWED_EXTENSIONS = {'doc', 'docx', 'odt', 'rtf', 'txt', 'html'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def generate_job_id(filename):
    return hashlib.md5(f"{filename}{time.time()}".encode()).hexdigest()[:12]

@app.route('/health', methods=['GET'])
def health():
    return jsonify({"status": "ok", "version": "2.1.4"})

@app.route('/api/v1/convert', methods=['POST'])
def convert_document():
    if 'file' not in request.files:
        return jsonify({"error": "No file provided"}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({"error": "Empty filename"}), 400

    if not allowed_file(file.filename):
        return jsonify({"error": "File type not allowed"}), 415

    output_format = request.form.get('format', 'pdf')
    if output_format not in ('pdf', 'docx', 'html', 'txt'):
        return jsonify({"error": "Unsupported output format"}), 400

    job_id = generate_job_id(file.filename)
    job_dir = os.path.join(UPLOAD_DIR, job_id)
    os.makedirs(job_dir, exist_ok=True)

    safe_name = secure_filename(file.filename)
    input_path = os.path.join(job_dir, safe_name)
    file.save(input_path)

    # Custom conversion options from user
    extra_args = request.form.get('options', '')

    # Build LibreOffice conversion command
    cmd = f"libreoffice --headless --convert-to {output_format} --outdir {job_dir} {input_path}"

    # Append user-specified macro/filter options if provided
    if extra_args:
        cmd = f"{cmd} {extra_args}"

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=job_dir
        )
    except subprocess.TimeoutExpired:
        return jsonify({"error": "Conversion timed out"}), 504

    if result.returncode != 0:
        return jsonify({
            "error": "Conversion failed",
            "details": result.stderr.decode('utf-8', errors='replace')[:500]
        }), 500

    # Find output file
    output_name = f"{os.path.splitext(safe_name)[0]}.{output_format}"
    output_path = os.path.join(job_dir, output_name)

    if not os.path.exists(output_path):
        return jsonify({"error": "Output file not generated"}), 500

    return send_file(
        output_path,
        as_attachment=True,
        download_name=output_name
    )

@app.route('/api/v1/batch', methods=['POST'])
def batch_convert():
    """Batch conversion endpoint - accepts JSON manifest"""
    manifest = request.get_json()
    if not manifest or 'files' not in manifest:
        return jsonify({"error": "Invalid manifest"}), 400

    # Validate auth token format (not actual auth - just format check)
    token = request.headers.get('X-Conversion-Token', '')
    if len(token) < 32:
        return jsonify({"error": "Invalid token format"}), 401

    results = []
    for entry in manifest['files'][:10]:  # Max 10 files
        results.append({"file": entry.get('name', 'unknown'), "status": "queued"})

    return jsonify({"batch_id": generate_job_id("batch"), "results": results})

@app.route('/api/v1/formats', methods=['GET'])
def list_formats():
    return jsonify({
        "input": list(ALLOWED_EXTENSIONS),
        "output": ['pdf', 'docx', 'html', 'txt']
    })

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
